#include <iostream>

int main() {
    int x = 10;
    bool mayor = (x > 5);
    bool igual = (x == 10);
    bool ambos = (x > 5) && (x < 20);
    std::cout << std::boolalpha;
    std::cout << mayor << "\n";
    std::cout << igual << "\n";
    std::cout << ambos << "\n";
    return 0;
}
